content.content:
 * The row above the calendar: one card per question, each a line of ask, a
 * handful of picture answers, and the exact numbers folded behind them. It has
 * no counterpart in the Fringe planner's stylesheet — that page states its
 * preferences as a strip of fields — so all of it is here.
 */
/* The Fringe planner rules its result off from the heading and paragraph above
   it. There is no heading here, so the rule would separate the card's own edge
   from the first question. */
.plan-result {
  margin-top: 0;
  border-top: none;
  padding-top: 0;
}
.prefs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: start;
  gap: 12px;
  margin-bottom: 18px;
}
.pref {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 12px 10px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
}
.pref-ask {
  margin: 0;
  font-family: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.25;
  color: var(--ink);
}
.pref-answers {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
/* An answer is its picture first: the word under it names the picture rather
   than the other way round, which is what makes the row scannable without
   being read. */
.pref-pick {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;
}
.pref-word {
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  overflow-wrap: anywhere;
}
.pref-expand {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: auto;
  padding: 2px 4px;
  border: none;
  background: none;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
}
.pref-expand:hover {
  color: var(--violet-dark);
}
.pref-expand:focus-visible {
  outline: 3px solid var(--violet);
  outline-offset: 2px;
  border-radius: 6px;
}
.pref-expand[aria-expanded="true"] .pref-caret {
  display: inline-block;
  transform: rotate(180deg);
}
.pref-fine {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px dashed var(--line);
}
.pref-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.pref-row--soon {
  justify-content: space-between;
}
.pref-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
}
/* A control the page is honest about not having wired yet — see leaf 21.4. */
.pref-soon {
  padding: 1px 7px;
  border: 1px dashed var(--line);
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.pref-note {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.45;
  color: var(--muted);
}
.pref-meal {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.pref-meal-on {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}
.pref-meal-times,
.pref-meal-place {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.pref-place {
  width: 128px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 0.8rem;
}
.pref-place:focus-visible {
  outline: 3px solid var(--violet);
  outline-offset: 2px;
}
.prefs .opt-select {
  height: 30px;
  padding: 0 8px;
  border-radius: 8px;
  font-size: 0.8rem;
}

@media (max-width: 1080px) {
  .prefs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 620px) {
  .prefs {
    grid-template-columns: minmax(0, 1fr);
  }
}

