/* What the reader filters the pool by, as rules: the kinds every festival
 * shares, a festival's own tags required or ruled out, and festivals left out.
 *
 * The kinds are the data pipeline's genre vocabulary
 * (scraper/festivals/registry.py's GENRES), which every festival block's
 * events carry; Edinburgh's genres are mapped onto it here, since its wire
 * format predates the vocabulary. Tags are each festival's own categories, the
 * pool ids lib/pool.js gives them.
 *
 * Pure: no DOM, no storage.
 */

import { festivalOf } from "./pool.js";

/** The shared kinds, in the order the kinds chip offers them. */
export const GENRES = ["film", "comedy", "theatre", "dance", "music", "family", "talk", "other"];

export const GENRE_EMOJI = {
  film: "🎬",
  comedy: "😂",
  theatre: "🎭",
  dance: "💃",
  music: "🎵",
  family: "🧸",
  talk: "🗣️",
  other: "🎟️",
};

/* Edinburgh's genres, which its wire format names in full. */
const EDFRINGE_GENRE = {
  "Comedy": "comedy",
  "Theatre": "theatre",
  "Cabaret and Variety": "comedy",
  "Children's Shows": "family",
  "Dance, Physical Theatre & Circus": "dance",
  "Events": "other",
  "Exhibitions": "other",
  "Music": "music",
  "Musicals and Opera": "theatre",
  "Spoken Word": "talk",
};

/** A shared kind for anything a festival calls its genre; unknown is "other". */
export function sharedGenre(genre) {
  if (GENRES.includes(genre)) return genre;
  return EDFRINGE_GENRE[genre] || "other";
}

/**
 * Whether a show survives the reader's filters.
 * @param {{slug: string, genreSlugs?: string[]}} show a pool show
 * @param {{festivalsOut?: Set<string>, tags?: Map<string, "only"|"out">}} filters
 */
export function passesFilters(show, { festivalsOut = new Set(), tags = new Map() } = {}) {
  if (festivalsOut.has(festivalOf(show.slug))) return false;
  const filed = show.genreSlugs || [];
  if (filed.some((tag) => tags.get(tag) === "out")) return false;
  const required = [...tags].filter(([, mode]) => mode === "only").map(([tag]) => tag);
  return !required.length || filed.some((tag) => required.includes(tag));
}

/** A tag's next state when clicked: neutral → only → out → neutral. */
export function nextTagMode(mode) {
  return mode === "only" ? "out" : mode === "out" ? null : "only";
}

"use strict";

// The rows ARE the requirement: which shows each filter keeps. verify() runs
// the shipped rule over three shows chosen so each row's answer can only come
// from the filter it names.
const TABLE = {
  columns: ["Filter", "Kept"],
  rows: [
    ["None", "every show"],
    ["A tag required", "only the shows filed under it"],
    ["Two tags required", "the shows filed under either"],
    ["A tag ruled out", "every show not filed under it"],
    ["A tag both required and ruled out on one show", "not that show: ruled out wins"],
    ["A festival left out", "none of that festival's shows"],
  ],
};

const SHOWS = [
  { slug: "haifa-iff/a", genreSlugs: ["haifa-iff/competition"] },
  { slug: "haifa-iff/b", genreSlugs: ["haifa-iff/panorama", "haifa-iff/family"] },
  { slug: "acco/c", genreSlugs: ["acco/premiere"] },
];

module.exports = {
  description: "a required tag keeps its shows, a ruled-out tag drops its shows, a festival left out drops all of them",
  table: TABLE,
  async verify(assert) {
    const { passesFilters } = await import("../../../../site/planNG/lib/filters.js");
    const kept = (filters) => SHOWS.filter((show) => passesFilters(show, filters)).map((s) => s.slug);

    assert.deepEqual(kept({}), ["haifa-iff/a", "haifa-iff/b", "acco/c"], "no filter keeps every show");
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/competition", "only"]]) }),
      ["haifa-iff/a"],
      "a required tag keeps only its shows, whichever festival the rest are from"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/competition", "only"], ["acco/premiere", "only"]]) }),
      ["haifa-iff/a", "acco/c"],
      "two required tags keep the shows under either"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/family", "out"]]) }),
      ["haifa-iff/a", "acco/c"],
      "a ruled-out tag drops only its shows"
    );
    assert.deepEqual(
      kept({ tags: new Map([["haifa-iff/panorama", "only"], ["haifa-iff/family", "out"]]) }),
      [],
      "ruled out wins over required on the same show"
    );
    assert.deepEqual(
      kept({ festivalsOut: new Set(["acco"]) }),
      ["haifa-iff/a", "haifa-iff/b"],
      "a festival left out drops all its shows"
    );
  },
};

